// The Worker entry point: the Next.js app (built by OpenNext) plus a daily
// cron job. See https://opennext.js.org/cloudflare/howtos/custom-worker
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`. This file is
// bundled by wrangler and left out of the Next.js type check (tsconfig).
import handler from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  /** Runs on the schedule in wrangler.jsonc ("triggers.crons"). */
  async scheduled(_controller, env, ctx) {
    // Reuse the app's own route, so the charge logic lives in one place.
    const request = new Request("https://cron.internal/api/cron/charges", {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then(async (response: Response) => {
        console.log("Monthly charges", response.status, await response.text());
      }),
    );
  },
} satisfies ExportedHandler<CloudflareEnv & { CRON_SECRET: string }>;
